const envelope = $('When Called by Another Workflow').first().json;
const rawRow = $input.first().json;
if (!rawRow || !rawRow.id) {
  return [{ json: { ok: false, http_status: 400, kind: 'bad_payload', message: 'raw_id_not_found' } }];
}
const order = rawRow.raw_payload;
const location_key = envelope.location_key;
const external_ref = envelope.external_ref;

function eurosToCents(s) { if (s == null) return 0; const n = typeof s === 'number' ? s : Number(s); return Number.isFinite(n) ? Math.round(n * 100) : 0; }
const GATEWAY_MAP = { shopify_payments: 'card_online', bogus: 'card_online', stripe: 'card_online', bancontact: 'bancontact', manual: 'cash', cod: 'cash', gift_card: 'voucher' };
function gatewayToMethod(g, names) { const gRaw = g || (Array.isArray(names) && names[0]) || null; if (!gRaw) return 'other'; const k = String(gRaw).toLowerCase().trim(); if (GATEWAY_MAP[k]) return GATEWAY_MAP[k]; if (k.includes('cash') || k.includes('cod')) return 'cash'; if (k.includes('bancontact')) return 'bancontact'; if (k.includes('gift')) return 'voucher'; return 'other'; }
function finStatusToPaymentStatus(s) { switch (s) { case 'paid': case 'authorized': case 'partially_paid': return 'paid'; case 'pending': return 'pending'; case 'refunded': return 'refunded'; case 'partially_refunded': return 'partial_refund'; case 'voided': case 'expired': return 'failed'; default: return 'pending'; } }
function extractUtm(arr) { if (!arr || !arr.length) return null; const m = new Map(arr.map(a => [a.name.toLowerCase(), a.value])); const get = k => { const v = m.get(k); return (v != null && v !== '') ? v : null; }; const u = { source: get('utm_source'), medium: get('utm_medium'), campaign: get('utm_campaign'), term: get('utm_term'), content: get('utm_content'), referrer_url: get('referrer') ?? get('referrer_url'), landing_page_url: get('landing_page') ?? get('landing_page_url') }; return Object.values(u).some(v => v !== null) ? u : null; }

// Compound SKU split: Shopify variants encode product+modifiers as 'B11__Veelsaus' or 'B17__ck3__colamenu'.
// Lightspeed catalog has only base PLU (B11, B17). We split on '__' and emit modifiers separately.
// parts[0] = base PLU sent as productPlu; parts[1..n] = modifier codes, paired with li.variant_title segments for human-readable names.
function splitCompoundSku(rawSku, variantTitle) {
  const parts = String(rawSku).split('__');
  const basePlu = parts[0];
  const modifierCodes = parts.slice(1);
  const vt = (variantTitle || '').trim();
  const modifierNames = (vt && vt !== 'Default Title') ? vt.split(' / ').map(p => p.trim()).filter(Boolean) : [];
  const modifiers = modifierCodes.map((code, idx) => ({ plu: '', name: modifierNames[idx] || code, unit_price_cents: 0 }));
  return { basePlu, modifiers };
}

try {
  if (!order || !Array.isArray(order.line_items) || order.line_items.length === 0 || !order.name) {
    return [{ json: { ok: false, http_status: 400, kind: 'bad_payload', message: 'invalid_shopify_payload' } }];
  }
  // A2: Shopify Local Pickup still sends shipping_lines + shipping_address (the shop's own
  // address), so presence alone misclassified ~10% of orders as delivery. Classify from the
  // shipping method title/code instead (Berlare: 'Afhaal [_230]', Aalst: 'Ophalen in frituur [_237]').
  const shipLine = (order.shipping_lines && order.shipping_lines[0]) || {};
  const shipLabel = String((shipLine.title || '') + ' ' + (shipLine.code || '')).toLowerCase();
  const isPickupMethod = /afhaal|afhalen|ophalen|pick[- ]?up|pickup/.test(shipLabel);
  const isDelivery = !isPickupMethod && ((Array.isArray(order.shipping_lines) && order.shipping_lines.length > 0) || order.shipping_address != null);
  const fullName = [order.customer?.first_name, order.customer?.last_name].filter(Boolean).join(' ').trim() || 'Guest';
  const items = order.line_items.map(li => {
    const rawSku = (li.sku && li.sku.length > 0) ? li.sku : ('SHOP-' + li.id);
    const { basePlu, modifiers } = splitCompoundSku(rawSku, li.variant_title);
    const it = { plu: basePlu, name: li.name, qty: li.quantity, unit_price_cents: eurosToCents(li.price) };
    if (modifiers.length > 0) it.modifiers = modifiers;
    const noteProp = (li.properties || []).find(p => p.name && p.name.toLowerCase() === 'notes');
    if (noteProp) it.notes = noteProp.value;
    return it;
  });
  // A5: 71% of orders had no phone — customer.phone is usually empty but shipping_address.phone
  // is filled. Fall back through all sources and normalize Belgian numbers to E.164.
  function normPhone(p) {
    if (!p) return null;
    const s = String(p).replace(/[\s\/.\-()]/g, '');
    if (/^\+/.test(s)) return s;
    if (/^00/.test(s)) return '+' + s.slice(2);
    if (/^0\d{8,9}$/.test(s)) return '+32' + s.slice(1);
    return s || null;
  }
  const phone = normPhone(order.customer?.phone) ?? normPhone(order.shipping_address?.phone) ?? normPhone(order.billing_address?.phone) ?? normPhone(order.phone) ?? null;
  const customer = { name: fullName, email: order.customer?.email ?? null, phone, address: null };
  if (isDelivery && order.shipping_address) {
    const a = order.shipping_address;
    // A6: line2 hygiene — drop it when it merely repeats line1 ("Leeuwerikenlaan 19" + "19")
    // or contains a stray postal code ("9310"); keep real bus/floor suffixes.
    let line2 = a.address2 != null ? String(a.address2).trim() : null;
    if (line2) {
      const l1n = String(a.address1 || '').toLowerCase().replace(/\s+/g, '');
      const l2n = line2.toLowerCase().replace(/\s+/g, '');
      if (!l2n || /^\d{4}$/.test(l2n) || l1n.includes(l2n)) line2 = null;
    }
    customer.address = { line1: a.address1, line2, postal_code: a.zip, city: a.city, country: (a.country_code ?? 'BE').toUpperCase().slice(0,2), lat: a.latitude ?? null, lng: a.longitude ?? null };
    // Delivery address without any house number — don't block the order, but flag it for
    // the counter/driver (surfaces via KLANT note on the LS ticket + Shipday instruction).
    const hasNumber = /\d/.test(String(a.address1 || '') + String(line2 || ''));
    if (!hasNumber) customer.notes = 'LET OP: huisnummer ontbreekt in adres — bel klant';
  }
  const totalCents = eurosToCents(order.total_price);
  const buckets = new Map();
  const add = (rate, base, vat) => { const rb = Math.round(rate * 10000); const c = buckets.get(rb) ?? { base: 0, vat: 0 }; c.base += base; c.vat += vat; buckets.set(rb, c); };
  for (const li of order.line_items) {
    const gross = eurosToCents(li.price) * li.quantity;
    const taxes = li.tax_lines || [];
    if (!taxes.length) add(0, gross, 0);
    else for (const tl of taxes) { const v = eurosToCents(tl.price); add(tl.rate, gross - v, v); }
  }
  for (const sl of order.shipping_lines || []) { const sg = eurosToCents(sl.price); if (sg > 0) add(0.21, sg, 0); }
  const vat_lines = Array.from(buckets.entries()).filter(([, v]) => v.base > 0 || v.vat > 0).map(([rb, v]) => ({ rate_bp: rb, base_cents: v.base, vat_cents: v.vat }));
  let sum = vat_lines.reduce((a, l) => a + l.base_cents + l.vat_cents, 0);
  if (vat_lines.length && sum !== totalCents) { let idx = 0; for (let i = 1; i < vat_lines.length; i++) if (vat_lines[i].base_cents > vat_lines[idx].base_cents) idx = i; vat_lines[idx].base_cents = Math.max(0, vat_lines[idx].base_cents + (totalCents - sum)); }
  const canonical = { schema_version: '1.1', source: 'shopify', external_ref, location_key, order_type: isDelivery ? 'delivery' : 'pickup', status: 'received', customer, items, payment: { method: gatewayToMethod(order.gateway, order.payment_gateway_names), status: finStatusToPaymentStatus(order.financial_status), total_cents: totalCents, currency: 'EUR' }, vat_lines, utm: extractUtm(order.note_attributes), refund_markers: null, cancel_reason: null };
  return [{ json: { ok: true, canonical, raw_id: rawRow.id, location_key, external_ref, is_delivery: isDelivery } }];
} catch (e) {
  return [{ json: { ok: false, http_status: 400, kind: 'bad_payload', message: 'normalizer_threw: ' + (e.message || 'unknown') } }];
}
